import {defaultFeatures} from './schema.mjs';
import {uid,today,validDate,validateBackup,validateTx,balance,fundingAccount,categoryList,inPeriod,cycleBounds} from './domain.mjs';
export function upgrade(state){const s=structuredClone(state);s.features=s.features||defaultFeatures();s.transactions=s.transactions.map(t=>({...t,bookId:t.bookId||'personal',tags:t.tags||[]}));return s}
const clone=s=>upgrade(s),check=(v,msg)=>{if(!v)throw Error(msg)},int=(n,min=0)=>Number.isSafeInteger(n)&&n>=min&&n<=1e12;
export function addDays(date,n){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
export function addMonths(date,n){const d=new Date(date+'T12:00:00Z'),anchor=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+n);const last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(last,anchor));return d.toISOString().slice(0,10)}
export function splitCents(total,count){check(int(total)&&Number.isInteger(count)&&count>0&&count<=120,'分期金額或期數不正確');const base=Math.floor(total/count),remainder=total%count;return Array.from({length:count},(_,i)=>base+(i<remainder?1:0))}
export function planRows(p){const principals=splitCents(p.totalPrincipal,p.count),fees=splitCents(p.totalFee,p.count);const paid=Array(p.count).fill(0),paidFees=Array(p.count).fill(0);for(const payment of p.payments)for(const a of payment.allocations){paid[a.index]+=a.principal;paidFees[a.index]+=a.fee}let refund=p.refunds.reduce((s,r)=>s+r.amount,0);const canceled=Array(p.count).fill(0);for(let i=p.count-1;i>=0;i--){canceled[i]=Math.min(refund,Math.max(0,principals[i]-paid[i]));refund-=canceled[i]}return principals.map((principal,i)=>({index:i,due:addMonths(p.firstDue,i),originalPrincipal:principal,principal:Math.max(0,principal-canceled[i]),paidPrincipal:paid[i],fee:fees[i],paidFee:paidFees[i],remaining:Math.max(0,principal-canceled[i]-paid[i]),remainingFee:Math.max(0,fees[i]-paidFees[i]),canceled:canceled[i]}))}
export function planRemaining(p){return planRows(p).reduce((n,r)=>n+r.remaining,0)}
export function createPlan(state,input){const s=clone(state);const account=s.accounts.find(a=>a.id===input.account);check(account&&['card','bnpl'].includes(account.kind),'分期請選信用卡或先買後付帳戶');check(int(input.totalPrincipal,1)&&int(input.totalFee)&&Number.isInteger(input.count)&&input.count>=1&&input.count<=120&&input.totalPrincipal>=input.count,'請確認金額與期數（每期本金至少0.01元）');check(validDate(input.firstDue)&&validDate(input.purchaseDate),'請填寫有效日期');check(input.name?.trim(),'請填寫方案名稱');check(s.accounts.some(a=>a.id===input.source)&&fundingAccount(s,input.source)!==account.id,'請選擇不同的實際付款帳戶');const id=uid();let purchaseTxId;
 if(input.existingTxId){const t=s.transactions.find(t=>t.id===input.existingTxId);check(t&&t.type==='expense'&&fundingAccount(s,t.account)===account.id&&!t.origin&&t.amount===input.totalPrincipal,'既有消費必須金額相同、使用同一扣款來源，且未關聯其他方案');purchaseTxId=t.id;t.origin={kind:'planPurchase',id};t.bookId=input.bookId;t.category=input.category}
 else{const t={id:uid(),type:'expense',amount:input.totalPrincipal,note:input.name.trim(),date:input.purchaseDate,category:input.category,account:input.account,toAccount:null,bookId:input.bookId,tags:['分期'],origin:{kind:'planPurchase',id}};validateTx(t,s);s.transactions.unshift(t);purchaseTxId=t.id}
 const plan={id,name:input.name.trim(),account:input.account,bookId:input.bookId,category:input.category,totalPrincipal:input.totalPrincipal,totalFee:input.totalFee,count:input.count,firstDue:input.firstDue,purchaseDate:input.purchaseDate,purchaseTxId,source:input.source,payments:[],refunds:[]};s.features.plans.push(plan);return validateBackup(s)}
export function editPlan(state,id,input){const s=clone(state),p=s.features.plans.find(x=>x.id===id);check(p,'找不到分期');check(Number.isInteger(input.count)&&input.count>=1&&input.count<=120&&input.count<=p.totalPrincipal&&validDate(input.firstDue)&&int(input.totalFee)&&input.name?.trim(),'名稱、日期、期數或費用不正確');check(!p.payments.length||input.count===p.count,'已有還款時，請保留原期數；可修改繳款日、名稱與預計費用');Object.assign(p,{name:input.name.trim(),count:input.count,firstDue:input.firstDue,totalFee:input.totalFee,source:input.source});return validateBackup(s)}
export function payPlan(state,id,{index=null,principal,fee,date=today(),source}){const s=clone(state),p=s.features.plans.find(x=>x.id===id);check(p,'找不到分期');check(validDate(date)&&int(principal,1)&&int(fee),'請填寫有效的實繳本金與費用');const rows=planRows(p),pool=index===null?rows:rows.filter(r=>r.index===index);check(principal<=pool.reduce((n,r)=>n+r.remaining,0),'實繳本金超過待還本金');check(s.accounts.some(a=>a.id===source)&&fundingAccount(s,source)!==p.account,'付款帳戶不能與分期來源相同');let remaining=principal;const allocations=[];for(const r of pool){const n=Math.min(r.remaining,remaining);if(n){allocations.push({index:r.index,principal:n,fee:0});remaining-=n}}allocations[0].fee=fee;const payId=uid(),transferTxId=uid();let feeTxId=null;if(fee){feeTxId=uid();s.transactions.unshift({id:feeTxId,type:'expense',amount:fee,note:p.name+' 實際手續費／利息',date,category:'手續費／利息',account:p.account,toAccount:null,bookId:p.bookId,tags:['分期費用'],origin:{kind:'planFee',id:p.id,relatedId:payId}})}const t={id:transferTxId,type:'transfer',amount:principal+fee,note:p.name+(index===null?' 提前／合併還款':' 第'+(index+1)+'期還款'),date,category:'其他',account:source,toAccount:p.account,bookId:p.bookId,tags:['分期還款'],origin:{kind:'planPayment',id:p.id,relatedId:payId}};validateTx(t,s);s.transactions.unshift(t);p.payments.push({id:payId,date,source,allocations,transferTxId,feeTxId});return validateBackup(s)}
export function refundPlan(state,id,{amount,date=today(),note='商品退款'}){const s=clone(state),p=s.features.plans.find(x=>x.id===id);check(p,'找不到分期');check(int(amount,1)&&amount<=p.totalPrincipal-p.refunds.reduce((n,r)=>n+r.amount,0),'退款超過尚可退的原始本金');const txId=uid(),r={id:uid(),amount,date,txId};s.transactions.unshift({id:txId,type:'refund',amount,note:p.name+' '+note,date,category:p.category,account:p.account,toAccount:null,bookId:p.bookId,tags:['分期退款'],origin:{kind:'planRefund',id:p.id,relatedId:r.id}});p.refunds.push(r);return validateBackup(s)}
export function billOccurrences(b,from,to){if(!b.active)return [];const result=[];for(let n=0;n<2400;n++){const due=b.interval==='weekly'?addDays(b.start,n*7):addMonths(b.start,n*(b.interval==='yearly'?12:1));if(due>to||(b.end&&due>b.end))break;if(due>=from)result.push(due);if(result.length>500)throw Error('日期範圍過大')}return result}
export function saveBill(state,input,id=null){const s=clone(state);check(validDate(input.start)&&(!input.end||validDate(input.end))&&(!input.end||input.end>=input.start),'固定收支日期不正確');validateTx({id:uid(),type:input.type,amount:input.amount,date:input.start,note:input.name,category:input.category,account:input.account,toAccount:input.toAccount},s);const bill={...input,id:id||uid(),end:input.end||null,active:input.active??true};const pos=s.features.bills.findIndex(b=>b.id===id);if(pos>=0)s.features.bills[pos]=bill;else s.features.bills.push(bill);return validateBackup(s)}
export function confirmBill(state,id,occurrence,{amount,date=today()}={}){const s=clone(state),b=s.features.bills.find(x=>x.id===id);check(b,'找不到固定收支');check(billOccurrences({...b,active:true},occurrence,occurrence).includes(occurrence),'非有效的固定收支日期');check(!s.transactions.some(t=>t.origin?.kind==='bill'&&t.origin.id===id&&t.origin.occurrence===occurrence),'這一期已經確認入帳，請勿重複');const t={id:uid(),type:b.type,amount:amount??b.amount,date,note:b.name,category:b.category,account:b.account,toAccount:b.toAccount,bookId:b.bookId,tags:['固定收支'],origin:{kind:'bill',id,occurrence}};validateTx(t,s);s.transactions.unshift(t);return validateBackup(s)}
export function upcoming(state,{from=addMonths(today(),-2),to=addMonths(today(),3),bookId=null,includeIncome=true}={}){const s=upgrade(state),events=[];for(const p of s.features.plans.filter(p=>!bookId||p.bookId===bookId))for(const r of planRows(p)){if(r.remaining>0&&r.due>=from&&r.due<=to)events.push({id:'plan:'+p.id+':'+r.index,kind:'plan',ref:p.id,index:r.index,name:p.name+' · 第'+(r.index+1)+'/'+p.count+'期',due:r.due,amount:r.remaining+r.remainingFee,principal:r.remaining,fee:r.remainingFee,type:'transfer',account:p.source,toAccount:p.account,bookId:p.bookId})}for(const b of s.features.bills.filter(b=>(!bookId||b.bookId===bookId)&&(includeIncome||b.type!=='income')))for(const due of billOccurrences(b,from,to)){if(!s.transactions.some(t=>t.origin?.kind==='bill'&&t.origin.id===b.id&&t.origin.occurrence===due))events.push({id:'bill:'+b.id+':'+due,kind:'bill',ref:b.id,name:b.name,due,amount:b.amount,type:b.type,account:b.account,toAccount:b.toAccount,bookId:b.bookId})}return events.sort((a,b)=>a.due.localeCompare(b.due)||a.id.localeCompare(b.id))}
export function balanceAt(s,id,date=today()){return balance({...s,transactions:s.transactions.filter(t=>t.date<=date)},id)}
export function liquidDelta(s,t){const isLiquid=id=>{const a=s.accounts.find(a=>a.id===fundingAccount(s,id));return a&&['cash','bank','mobile'].includes(a.kind)};let delta=isLiquid(t.account)?(t.type==='expense'||t.type==='transfer'?-t.amount:t.amount):0;if(t.type==='transfer'&&isLiquid(t.toAccount))delta+=t.amount;return delta}
export function forecast(state,days=30,date=today()){const s=upgrade(state),to=addDays(date,days),pending=upcoming(s,{from:addMonths(date,-12),to});const initial=s.accounts.filter(a=>['cash','bank','mobile'].includes(a.kind)&&!(a.kind==='mobile'&&a.paymentMode==='linked')).reduce((n,a)=>n+balanceAt(s,a.id,date),0);const events=pending.map(e=>({...e,date:e.due<date?date:e.due,delta:liquidDelta(s,e),estimated:true}));for(const t of s.transactions.filter(t=>t.date>date&&t.date<=to))events.push({id:t.id,name:t.note,date:t.date,amount:t.amount,type:t.type,delta:liquidDelta(s,t),estimated:false});events.sort((a,b)=>a.date.localeCompare(b.date));let current=initial;const daily=Array.from({length:days+1},(_,i)=>{const d=addDays(date,i);const dayEvents=events.filter(e=>e.date===d);current+=dayEvents.reduce((n,e)=>n+e.delta,0);return {date:d,balance:current,events:dayEvents}});return {initial,end:current,minimum:Math.min(initial,...daily.map(x=>x.balance)),daily,events}}
export function duplicates(state){const groups=new Map();for(const t of state.transactions){const key=JSON.stringify([t.date,t.amount,t.type,fundingAccount(state,t.account),t.note.trim().toLowerCase()]);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(t)}return [...groups.values()].filter(g=>g.length>1)}
export function reconcile(state,{account,date=today(),actual,note='',adjust=false,bookId='personal'}){const s=clone(state),expected=balanceAt(s,account,date),difference=actual-expected;check(int(Math.abs(actual))&&validDate(date),'對帳金額或日期不正確');const id=uid();let txId=null;if(adjust&&difference){if(!s.features.categories.includes('對帳調整'))s.features.categories.push('對帳調整');txId=uid();s.transactions.unshift({id:txId,type:difference>0?'income':'expense',amount:Math.abs(difference),date,note:'對帳調整'+(note?'：'+note:''),category:'對帳調整',account,toAccount:null,bookId,tags:['對帳調整'],origin:{kind:'reconcile',id}})}s.features.reconciliations.unshift({id,account,date,actual,expected,difference,note,txId});s.features.reconciliations=s.features.reconciliations.slice(0,1000);return validateBackup(s)}
export function trashTransaction(state,id){const s=clone(state),t=s.transactions.find(t=>t.id===id);check(t,'找不到紀錄');check(!t.origin||t.origin.kind==='bill','此紀錄與分期／對帳關聯，請從對應管理頁操作，避免破壞資料');s.transactions=s.transactions.filter(x=>x.id!==id);s.features.trash.unshift({id:uid(),deletedAt:Date.now(),tx:t});s.features.trash=s.features.trash.slice(0,100);return validateBackup(s)}
export function restoreTransaction(state,id){const s=clone(state),item=s.features.trash.find(t=>t.id===id);check(item,'找不到刪除紀錄');check(!s.transactions.some(t=>t.id===item.tx.id),'這筆已經存在');if(item.tx.origin?.kind==='bill')check(!s.transactions.some(t=>t.origin?.kind==='bill'&&t.origin.id===item.tx.origin.id&&t.origin.occurrence===item.tx.origin.occurrence),'該固定收支已重新入帳，請先確認重複紀錄');s.transactions.unshift(item.tx);s.features.trash=s.features.trash.filter(t=>t.id!==id);return validateBackup(s)}
export function bookTransactions(state,bookId){return state.transactions.filter(t=>!bookId||(t.bookId||'personal')===bookId)}
export function budgetStatus(state,month,bookId='personal'){const s=upgrade(state),limits=s.features.categoryBudgets[bookId+':'+month]||{},spend=Object.create(null);for(const t of bookTransactions(s,bookId).filter(t=>inPeriod(t.date,month,s.features.cycleDay))){if(t.type==='expense'||t.type==='refund')spend[t.category]=(spend[t.category]||0)+(t.type==='refund'?-t.amount:t.amount)}return Object.entries(limits).map(([category,limit])=>({category,limit,used:spend[category]||0,remaining:limit-(spend[category]||0)}))}
const escapeICS=s=>String(s).replaceAll('\\','\\\\').replace(/\r\n|\r|\n/g,'\\n').replaceAll(',','\\,').replaceAll(';','\\;');
export function calendarICS(events,{advanceDays=1,stamp=new Date().toISOString()}={}){const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Yoyu Ledger//Bills//ZH-TW','CALSCALE:GREGORIAN','METHOD:PUBLISH'];for(const e of events){const day=e.due.replaceAll('-','');lines.push('BEGIN:VEVENT','UID:'+escapeICS(e.id)+'@yoyu-ledger','DTSTAMP:'+stamp.replace(/[-:]/g,'').replace(/\.\d+Z$/,'Z'),'DTSTART;VALUE=DATE:'+day,'DTEND;VALUE=DATE:'+addDays(e.due,1).replaceAll('-',''),'SUMMARY:'+escapeICS(e.name),'DESCRIPTION:'+escapeICS('預計金額 NT$'+(e.amount/100).toFixed(2)+'。請回記帳工具確認實際付款，勿重複入帳。'),'BEGIN:VALARM','TRIGGER:-P'+advanceDays+'D','ACTION:DISPLAY','DESCRIPTION:繳款提醒','END:VALARM','END:VEVENT')}lines.push('END:VCALENDAR');return lines.join('\r\n')+'\r\n'}

export function reversePlanPayment(state,planId,paymentId){const s=clone(state),p=s.features.plans.find(p=>p.id===planId);check(p,'找不到分期');const pay=p.payments.find(x=>x.id===paymentId);check(pay,'找不到實繳紀錄');s.transactions=s.transactions.filter(t=>t.id!==pay.transferTxId&&t.id!==pay.feeTxId);p.payments=p.payments.filter(x=>x.id!==paymentId);return validateBackup(s)}
export function reversePlanRefund(state,planId,refundId){const s=clone(state),p=s.features.plans.find(p=>p.id===planId);check(p,'找不到分期');const r=p.refunds.find(x=>x.id===refundId);check(r,'找不到退款紀錄');s.transactions=s.transactions.filter(t=>t.id!==r.txId);p.refunds=p.refunds.filter(x=>x.id!==refundId);return validateBackup(s)}
